//! Committed outputs generated by the pinned Go implementation, not hand-written
//! expectations. The oracle is development-only and is not needed by `cargo test`.
use relaykit::{Context, Format, Request};
use serde_json::{Value, json};
use std::sync::Arc;

#[test]
fn upstream_reasoning_cases() {
    let corpus: Value =
        serde_json::from_str(include_str!("fixtures/reasoning_parity.json")).unwrap();
    let mut failures = Vec::new();
    for entry in corpus.as_array().unwrap() {
        let case = &entry["case"];
        if let Ok(filter) = std::env::var("CASE_FILTER") {
            if !case["name"].as_str().unwrap().contains(&filter) {
                continue;
            }
        }
        let from: Format = case["from"].as_str().unwrap().parse().unwrap();
        let to: Format = case["to"].as_str().unwrap().parse().unwrap();
        let model = case["model"].as_str().unwrap_or("");
        let mut ctx = Context {
            channel_meta_attached: !model.is_empty(),
            upstream_model_name: model.into(),
            ..Default::default()
        };
        ctx.media.get_base64_data =
            Some(Arc::new(|_, _| Ok(("aGVsbG8=".into(), "image/png".into()))));
        ctx.media.decode_base64_file_data =
            Some(Arc::new(|_| Ok(("aGVsbG8=".into(), "image/png".into()))));
        if case["golden"] == true {
            ctx.options.gemini.function_call_thought_signature_enabled = true;
            ctx.options.gemini.thinking_adapter_budget_tokens_percentage = 0.6;
            ctx.options.gemini.safety_setting = Some(Arc::new(|_| "OFF".into()));
        }
        ctx.origin_model_name = case["origin_model"].as_str().unwrap_or("").into();
        ctx.options.open_router_dialect = case["open_router"] == true;
        ctx.options.claude.thinking_adapter_enabled = case["claude_adapter"] == true;
        ctx.options.gemini.thinking_adapter_enabled = case["gemini_adapter"] == true;
        if let Some(p) = case["adapter_percentage"].as_f64() {
            ctx.options.claude.thinking_adapter_budget_tokens_percentage = p;
            ctx.options.gemini.thinking_adapter_budget_tokens_percentage = p;
        }
        if let Some(state) = case.get("reasoning_conversion") {
            ctx.reasoning_conversion = Some(relaykit::reasoning::Intent {
                mode: state["Mode"].as_str().unwrap_or("").into(),
                effort: state["Effort"].as_str().unwrap_or("").into(),
                budget_tokens: state["BudgetTokens"].as_i64(),
                include_thoughts: state["IncludeThoughts"].as_bool(),
                source: "suffix".into(),
                budget_source: "suffix".into(),
            });
        }
        let result = Request::from_value(from, case["input"].clone())
            .and_then(|request| relaykit::convert_request(&ctx, to, &request));
        let expected = &entry["expected"];
        let actual = match result {
            Ok(result) => {
                json!({"value": result.value.into_value(), "diagnostics": result.diagnostics})
            }
            Err(error) => json!({"error": error.to_string()}),
        };
        if actual.get("error").is_some() && expected.get("error").is_some() {
            continue;
        }
        let wanted = if expected.get("error").is_some() {
            json!({"error": expected["error"]})
        } else {
            json!({"value": expected["value"], "diagnostics": expected["diagnostics"].as_array().cloned().unwrap_or_default()})
        };
        if actual != wanted {
            failures.push(json!({"case":case, "actual":actual, "expected":wanted}));
        }
    }
    if !failures.is_empty() {
        let path = std::env::temp_dir().join("relaykit-reasoning-diff.json");
        std::fs::write(&path, serde_json::to_string_pretty(&failures).unwrap()).unwrap();
        panic!(
            "{} reasoning cases differ; see {}:\n{}",
            failures.len(),
            path.display(),
            failures
                .iter()
                .map(|v| v["case"]["name"].as_str().unwrap())
                .collect::<Vec<_>>()
                .join("\n")
        );
    }
}
